/**
 * dashboard-client/src/tabs/MaintenanceTab.tsx — Maintenance tab (S49B).
 *
 * Schema health audit + DB stats + maintenance action triggers.
 * Polls schema-health every 10s and db-stats every 15s (stats are stable).
 */

import type React from "react";
import { useState, useCallback } from "react";
import type {
	DbStatsResponse,
	SchemaHealthResponse,
	MaintenanceAction,
	MaintenanceActionResult,
	TableStats,
	DbFiles,
	SchemaHealthRow,
} from "@contracts";
import { useApi } from "../hooks/useApi";
import { fetchDbStats, fetchSchemaHealth, postMaintenanceAction } from "../api/client";

// ---------------------------------------------------------------------------
// DB Stats Card
// ---------------------------------------------------------------------------

function DbStatsCard({ data, loading, error }: {
	data: DbStatsResponse | null;
	loading: boolean;
	error: Error | null;
}) {
	return (
		<div className="card">
			<div className="card-header">DB Stats</div>
			<div className="card-body">
				{loading && !data && <span className="text-muted">Loading…</span>}
				{error && !data && <span className="text-error">{error.message}</span>}
				{data && (
					<>
						<FileSizes files={data.storage.files} pageSize={data.storage.pageSize} pageCount={data.storage.pageCount} freelistPages={data.storage.freelistPages} />
						<TableCounts tables={data.tables} />
					</>
				)}
			</div>
		</div>
	);
}

function fmtBytes(b: number): string {
	if (b < 1024) return `${b} B`;
	if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} KB`;
	return `${(b / (1024 * 1024)).toFixed(1)} MB`;
}

function FileSizes({ files, pageSize, pageCount, freelistPages }: {
	files: DbFiles;
	pageSize: number;
	pageCount: number;
	freelistPages: number;
}) {
	return (
		<div className="stat-section">
			<div className="stat-label">File Sizes</div>
			<table className="compact-table">
				<tbody>
					<tr><td>sqlite.db</td><td className="num">{fmtBytes(files.dbBytes)}</td></tr>
					{files.walBytes > 0 && <tr><td>.wal</td><td className="num">{fmtBytes(files.walBytes)}</td></tr>}
					{files.shmBytes > 0 && <tr><td>.shm</td><td className="num">{fmtBytes(files.shmBytes)}</td></tr>}
					<tr><td>Total</td><td className="num">{fmtBytes(files.dbBytes + files.walBytes + files.shmBytes)}</td></tr>
					<tr><td>Page size</td><td className="num">{fmtBytes(pageSize)}</td></tr>
					<tr><td>Pages</td><td className="num">{pageCount.toLocaleString()} ({freelistPages.toLocaleString()} free)</td></tr>
				</tbody>
			</table>
		</div>
	);
}

function TableCounts({ tables }: { tables: TableStats[] }) {
	const total = tables.reduce((sum, t) => sum + Math.max(0, t.rowCount), 0);
	return (
		<div className="stat-section">
			<div className="stat-label">Table Row Counts ({total.toLocaleString()} total)</div>
			<table className="compact-table">
				<thead>
					<tr><th>Table</th><th className="num">Rows</th></tr>
				</thead>
				<tbody>
					{tables.map((t) => (
						<tr key={t.table}>
							<td>{t.table}</td>
							<td className="num">{t.rowCount >= 0 ? t.rowCount.toLocaleString() : "—"}</td>
						</tr>
					))}
				</tbody>
			</table>
		</div>
	);
}

// ---------------------------------------------------------------------------
// Schema Health Card
// ---------------------------------------------------------------------------

function SchemaHealthCard({ data, loading, error }: {
	data: SchemaHealthResponse | null;
	loading: boolean;
	error: Error | null;
}) {
	return (
		<div className="card">
			<div className="card-header">
				Schema Health
				{data && (
					<span className={`badge ${data.healthy ? "badge-ok" : "badge-bad"}`}>
						{data.healthy ? "HEALTHY" : "DEGRADED"}
					</span>
				)}
			</div>
			<div className="card-body">
				{loading && !data && <span className="text-muted">Loading…</span>}
				{error && !data && <span className="text-error">{error.message}</span>}
				{data && (
					<>
						<div className="stat-row"><span className="stat-label">Schema version</span><span className="num">{data.schemaVersion}</span></div>
						<div className="stat-row"><span className="stat-label">Integrity</span><span className={data.integrity[0] === "ok" ? "text-ok" : "text-error"}>{data.integrity.join("; ")}</span></div>
						<ColumnAudit columns={data.columns} />
						{data.fkCheck.length > 0 && (
							<div className="stat-section">
								<div className="stat-label text-warn">FK Check ({data.fkCheck.length})</div>
								{data.fkCheck.map((fk, i) => <div key={i} className="text-warn text-mono">{fk}</div>)}
							</div>
						)}
					</>
				)}
			</div>
		</div>
	);
}

function ColumnAudit({ columns }: { columns: SchemaHealthRow[] }) {
	const missing = columns.filter((c) => !c.present);
	return (
		<div className="stat-section">
			<div className="stat-label">Column Audit ({columns.length} columns, {missing.length} missing)</div>
			<table className="compact-table">
				<thead>
					<tr><th>Table</th><th>Column</th><th>Decl</th><th>Status</th></tr>
				</thead>
				<tbody>
					{columns.map((c) => (
						<tr key={`${c.table}.${c.column}`}>
							<td>{c.table}</td>
							<td>{c.column}</td>
							<td className="text-mono">{c.expectedDecl}</td>
							<td className={c.present ? "text-ok" : "text-error"}>{c.present ? "✓" : "MISSING"}</td>
						</tr>
					))}
				</tbody>
			</table>
		</div>
	);
}

// ---------------------------------------------------------------------------
// Action Card
// ---------------------------------------------------------------------------

const ACTIONS: Array<{
	key: string;
	label: string;
	desc: string;
	dangerous: boolean;
	confirm?: string;
	daysOld?: boolean;
}> = [
	{ key: "integrity-check", label: "Integrity Check", desc: "Run PRAGMA integrity_check", dangerous: false },
	{ key: "reconcile-dedup", label: "Reconcile Dedup Mirror", desc: "Fix orphan dedup rows + backfill refs", dangerous: false, confirm: "Reconcile dedup_mirror (safe read/write)?" },
	{ key: "checkpoint", label: "WAL Checkpoint", desc: "Merge WAL into main DB (read-only)", dangerous: false },
	{ key: "vacuum", label: "VACUUM", desc: "Rebuild DB reclaiming free pages", dangerous: true, confirm: "VACUUM rewrites the entire DB. Continue?" },
	{ key: "reindex", label: "REINDEX", desc: "Rebuild all indexes", dangerous: true, confirm: "REINDEX rebuilds indexes. Continue?" },
	{ key: "fts5-rebuild", label: "FTS5 Rebuild", desc: "Rebuild full-text search index", dangerous: true, confirm: "Rebuild FTS5 trigram index. Continue?" },
	{ key: "prune", label: "Prune Old Rows", desc: "Delete transcripts + epochs older than N days", dangerous: true, daysOld: true, confirm: "Delete old raw_transcript rows. Continue?" },
];

interface ActionResult extends MaintenanceActionResult {
	timestamp: number;
}

function ActionsPanel() {
	const [results, setResults] = useState<ActionResult[]>([]);
	const [running, setRunning] = useState<string | null>(null);
	const [days, setDays] = useState("30");

	const run = useCallback(async (def: typeof ACTIONS[number], daysOverride?: string) => {
		const payload: MaintenanceAction = (def.daysOld
			? { action: "prune", daysOld: Number(daysOverride ?? days) }
			: { action: def.key }) as MaintenanceAction;

		setRunning(def.key);
		try {
			const res = await postMaintenanceAction(payload);
			setResults((prev) => [{ ...res, timestamp: Date.now() }, ...prev].slice(0, 20));
		} catch (err) {
			setResults((prev) => [{
				operation: def.key,
				success: false,
				affected: 0,
				reclaimedBytes: 0,
				summary: (err as Error).message,
				timestamp: Date.now(),
			}, ...prev].slice(0, 20));
		} finally {
			setRunning(null);
		}
	}, [days]);

	return (
		<div className="card">
			<div className="card-header">Actions</div>
			<div className="card-body">
				<div className="action-grid">
					{ACTIONS.map((a) => {
						const isRunning = running === a.key;
						const lastResult = results.find((r) => r.operation === a.key);
						return (
							<div key={a.key} className="action-item">
								<div className="action-info">
									<div className="action-label">
										{a.label}
										{a.dangerous && <span className="badge badge-warn">DESTRUCTIVE</span>}
									</div>
									<div className="action-desc">{a.desc}</div>
									{lastResult && (
										<div className={`action-result ${lastResult.success ? "text-ok" : "text-error"}`}>
											{lastResult.summary}
										</div>
									)}
								</div>
								<div className="action-controls">
									{a.daysOld && (
										<input
											type="number"
											min="1"
											max="365"
											value={days}
											onChange={(e) => setDays(e.target.value)}
											className="days-input"
											disabled={isRunning}
										/>
									)}
									<button
										className={`btn ${a.dangerous ? "btn-danger" : "btn-primary"}`}
										disabled={isRunning !== null}
										onClick={() => {
											if (a.confirm && !window.confirm(a.confirm)) return;
											run(a);
										}}
									>
										{isRunning ? "Running…" : "Run"}
									</button>
								</div>
							</div>
						);
					})}
				</div>
			</div>
		</div>
	);
}

// ---------------------------------------------------------------------------
// Tab root
// ---------------------------------------------------------------------------

export default function MaintenanceTab(): React.ReactElement {
	const { data: stats, loading: statsLoading, error: statsError } = useApi<DbStatsResponse>(
		useCallback(() => fetchDbStats(), []),
		{ pollInterval: 15000 },
	);
	const { data: schema, loading: schemaLoading, error: schemaError } = useApi<SchemaHealthResponse>(
		useCallback(() => fetchSchemaHealth(), []),
		{ pollInterval: 10000 },
	);

	return (
		<div className="maintenance-tab">
			<div className="card-grid">
				<SchemaHealthCard data={schema} loading={schemaLoading} error={schemaError} />
				<DbStatsCard data={stats} loading={statsLoading} error={statsError} />
			</div>
			<ActionsPanel />
		</div>
	);
}
